<?php
namespace App\Models; use App\Enums\BookingStatus; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo;use Illuminate\Database\Eloquent\Relations\HasOne;
class Booking extends Model {protected $fillable=['booking_code','customer_id','vehicle_id','start_datetime','end_datetime','pickup_location','return_location','use_driver','driver_type','rental_days','base_price','driver_price','discount_amount','subtotal','tax_amount','deposit_amount','total_amount','status','payment_expires_at','customer_notes']; protected function casts():array{return ['start_datetime'=>'datetime','end_datetime'=>'datetime','payment_expires_at'=>'datetime','use_driver'=>'boolean','status'=>BookingStatus::class];} public function vehicle():BelongsTo{return $this->belongsTo(Vehicle::class);} public function customer():BelongsTo{return $this->belongsTo(Customer::class);}public function invoice():HasOne{return $this->hasOne(Invoice::class);}}
